#include "cuda_utils.cuh"
#include <vector>
#include <iostream>
#define T 16
__global__ void gemm(const float*A,const float*B,float*C,int n){__shared__ float As[T][T],Bs[T][T];int r=blockIdx.y*T+threadIdx.y,c=blockIdx.x*T+threadIdx.x;float acc=0;for(int q=0;q<(n+T-1)/T;q++){int ac=q*T+threadIdx.x,br=q*T+threadIdx.y;As[threadIdx.y][threadIdx.x]=(r<n&&ac<n)?A[r*n+ac]:0;Bs[threadIdx.y][threadIdx.x]=(br<n&&c<n)?B[br*n+c]:0;__syncthreads();for(int k=0;k<T;k++)acc+=As[threadIdx.y][k]*Bs[k][threadIdx.x];__syncthreads();}if(r<n&&c<n)C[r*n+c]=acc;}
int main(){const int BATCH=8,N=128;size_t bytes=N*N*4;std::vector<std::vector<float>>hA(BATCH,std::vector<float>(N*N)),hB=hA,hC=hA;std::vector<float*>dA(BATCH),dB(BATCH),dC(BATCH);std::vector<cudaStream_t>s(BATCH);for(int b=0;b<BATCH;b++){for(int i=0;i<N*N;i++){hA[b][i]=(i%7)*.1f;hB[b][i]=((i+b)%11)*.05f;}CUDA_CHECK(cudaStreamCreate(&s[b]));CUDA_CHECK(cudaMalloc(&dA[b],bytes));CUDA_CHECK(cudaMalloc(&dB[b],bytes));CUDA_CHECK(cudaMalloc(&dC[b],bytes));CUDA_CHECK(cudaMemcpyAsync(dA[b],hA[b].data(),bytes,cudaMemcpyHostToDevice,s[b]));CUDA_CHECK(cudaMemcpyAsync(dB[b],hB[b].data(),bytes,cudaMemcpyHostToDevice,s[b]));dim3 block(T,T),grid((N+T-1)/T,(N+T-1)/T);gemm<<<grid,block,0,s[b]>>>(dA[b],dB[b],dC[b],N);check_kernel("gemm");CUDA_CHECK(cudaMemcpyAsync(hC[b].data(),dC[b],bytes,cudaMemcpyDeviceToHost,s[b]));}CUDA_CHECK(cudaDeviceSynchronize());for(int b=0;b<BATCH;b++){int r=17,c=31;float ref=0;for(int k=0;k<N;k++)ref+=hA[b][r*N+k]*hB[b][k*N+c];if(!nearly_equal(hC[b][r*N+c],ref,1e-3f,1e-3f))return 1;CUDA_CHECK(cudaFree(dA[b]));CUDA_CHECK(cudaFree(dB[b]));CUDA_CHECK(cudaFree(dC[b]));CUDA_CHECK(cudaStreamDestroy(s[b]));}std::cout<<"PASS\n";}
